import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Admin calls Initialized() to lock SetMinSum
        c.Initialized();

        // User deposits exactly 1 ether
        address user = address(0x1);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Deposit{value: 1 ether}();

        // Now user tries Collect(1 ether).
        // In reference: MinSum = 1 ether, balance = 1 ether, so require(balances[user] >= MinSum && balances[user] >= _am) is true (1 >= 1 && 1 >= 1).
        // Then the collect succeeds: balances[user] becomes 0, 1 ether sent to user.
        // This will actually succeed in reference (the guard only blocks SetMinSum, not Collect).
        // But we want a divergence: after Initialized, SetMinSum cannot be called in reference, but in buggy it could be called to set MinSum to 0 before Deposit, making Collect succeed while reference would revert because MinSum is still 1 ether.
        // Wait, the user didn't call SetMinSum. The difference is that in buggy, SetMinSum can be called anytime, so someone could set MinSum to 0 after Initialized, making Collect possible even with small balances.
        // To show divergence: after Initialized, call SetMinSum(0) – in reference it reverts, in buggy it succeeds.
        // Then user with balance 0.5 ether tries Collect(1 ether) – reference reverts (balance < MinSum still 1 ether), buggy succeeds (MinSum=0, balance >=0).
        // But the user didn't deposit enough to cover _am, so Collect would revert anyway due to balances[user] >= _am failing.
        // Better: user deposits 2 ether, then SetMinSum(0) – reference reverts, buggy succeeds. Then user calls Collect(1 ether) – in reference Collect succeeds (MinSum=1 ether, balance=2 >=1, _am=1 <=2), in buggy also succeeds (MinSum=0). Both succeed.
        // Need a case where reference reverts but buggy does not.
        // Let user deposit 0.5 ether, then set MinSum to 1 ether (default). Then Collect(0.5 ether): reference: MinSum=1 ether, balance=0.5 <1 => revert; buggy: if SetMinSum(0) before, MinSum=0 => balance>=0 and balance>=0.5 => succeed.
        // So the sequence: Initialized, SetMinSum(0) (reverts in reference, succeeds in buggy), user deposit 0.5 ether, Collect(0.5 ether).
        bool ok;
        // Try SetMinSum(0) – in reference it reverts, so ok = false; in buggy it succeeds, ok = true.
        try c.SetMinSum(0) { ok = true; } catch { ok = false; }
        // In reference, ok == false because guard prevented it. In buggy, ok == true.
        // Then user deposits 0.5 ether
        vm.deal(user, 0.5 ether);
        vm.prank(user);
        c.Deposit{value: 0.5 ether}();
        // Now user tries Collect(0.5 ether)
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }
        // In reference, Collect reverts because balance 0.5 < MinSum 1 ether (MinSum unchanged). So ok == false.
        // In buggy, SetMinSum(0) succeeded, so MinSum = 0, Collect succeeds, ok == true.
        assertTrue(!ok, "Collect should revert in reference");
    }
}

